  const n = Array.isArray(heights[0]) ? heights[0].length : 0;
  if (n < 1 || n > 400) return 'Each row needs 1 to 400 people.';
  for (const row of heights) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each height is a whole number from 1 to 10^5.';
  }
  return null;
}

