function seePeople(heights) {
  const rows = heights.length;
  const cols = heights[0].length;
  const answer = heights.map(row => row.map(() => 0));

  function countVisible(stack, height) {
    let seen = 0;
    while (stack.length > 0 && stack[stack.length - 1] < height) {
      stack.pop();
      seen++;
    }
    if (stack.length > 0) {
      seen++;
    }
    if (stack.length > 0 && stack[stack.length - 1] === height) {
      stack.pop();
    }
    stack.push(height);
    return seen;
  }

  for (let i = 0; i < rows; i++) {
    const stack = [];
    for (let j = cols - 1; j >= 0; j--) {
      answer[i][j] += countVisible(stack, heights[i][j]);
    }
  }
  for (let j = 0; j < cols; j++) {
    const stack = [];
    for (let i = rows - 1; i >= 0; i--) {
      answer[i][j] += countVisible(stack, heights[i][j]);
    }
  }
  return answer;
}

