  const m = heights.length, n = heights[0].length;
  const result = [];
  for (let r = 0; r < m; r++) {
    const line = [];
    for (let c = 0; c < n; c++) {
      const me = heights[r][c];
      let total = 0;
      let tallest = 0;
      for (let k = c + 1; k < n; k++) {
        if (tallest < Math.min(me, heights[r][k])) total++;
        tallest = Math.max(tallest, heights[r][k]);
      }
      tallest = 0;
      for (let k = r + 1; k < m; k++) {
        if (tallest < Math.min(me, heights[k][c])) total++;
        tallest = Math.max(tallest, heights[k][c]);
      }
      line.push(total);
    }
    result.push(line);
  }
  return result;
}

