function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const m = large ? int(60, 100) : int(1, 5);
  const n = large ? int(60, 100) : int(1, 5);
  const top = [2, 4, 10, 100000][int(0, 3)];
  const style = rand();
  const heights = [];
  for (let i = 0; i < m; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      let value;
      if (style < 0.2) value = Math.max(1, Math.min(top, 1 + ((i + j) % top)));
      else if (style < 0.3) value = Math.max(1, top - ((i * n + j) % top));
      else value = int(1, top);
      row.push(value);
    }
    heights.push(row);
  }
  return [heights];
}
